na cuota legal panameña.","Reserva utilizable igual al agua almacenada solo por hipótesis de este ensayo; la calidad real no se ha comprobado.","Tanques nominales de 5000 L o banco equivalente de dos tanques de 5000 L. No se afirma que existan en estas instalaciones.","Margen de almacenamiento 5%, caudal de descarga 300 L/min y preparación 5 min son decisiones arbitrarias de modelado, no normas.","CASO FICTICIO: grupo domiciliario; nivel de vulnerabilidad inventado para probar ponderaciones.","Grupos vecinales ficticios asociados a referencias documentales; no son mediciones o diagnósticos de las instalaciones."]}}}]$casos$::jsonb; c jsonb; p jsonb; eid uuid; u uuid; r jsonb; toma jsonb; base jsonb; n integer;
 v uuid:=gen_random_uuid(); rr uuid:=gen_random_uuid(); ee uuid:=gen_random_uuid(); ii uuid:=gen_random_uuid(); pp uuid; ss uuid;
BEGIN
 u:=(casos->0->'paquete'->'revision'->>'usuario_id')::uuid;
 INSERT INTO auth.users(id) VALUES(u);
 INSERT INTO public.usuarios_operativos(usuario_id,rol,activo,motivo) VALUES(u,'coordinador',true,'Coordinador ficticio del smoke V2');
 -- Reporte anterior de otro ámbito: debe quedar intacto.
 SELECT punto_atencion_id,sector_id INTO pp,ss FROM public.puntos_atencion LIMIT 1;
 INSERT INTO public.remitentes(remitente_ref,canal,identificador_externo) VALUES(v,'panel',v::text);
 INSERT INTO public.reportes(reporte_id,remitente_ref,canal,mensaje_externo_id,modalidad,texto,origen,interpretacion)
 VALUES(rr,v,'panel',rr::text,'texto','Reporte sintético anterior','sintetico','{}');
 INSERT INTO public.ejecuciones(ejecucion_id,reporte_id,origen,etapa) VALUES(ee,rr,'sintetico','priorizacion');
 INSERT INTO public.incidentes(incidente_id,ejecucion_id,punto_atencion_id,sector_id,periodo_inicio,periodo_fin,primera_deteccion_en,origen)
 VALUES(ii,ee,pp,ss,now()-interval '1 hour',now(),now(),'sintetico');
 INSERT INTO public.vinculos_reportes(incidente_id,reporte_id,motivo) VALUES(ii,rr,'Reporte anterior de control');
 base:=public.ra_incidentes_snapshot_v2();
 PERFORM set_config('role','service_role',true);
 FOR c IN SELECT value FROM jsonb_array_elements(casos) LOOP
  p:=c->'paquete';eid:=(p->>'ejecucion_id')::uuid;
  r:=public.ra_registrar_ensayo_priorizacion_v2(u,p,'Revisión ficticia del smoke');
  IF jsonb_array_length(public.ra_incidentes_contexto_v2(eid))<>6 THEN RAISE EXCEPTION 'Lote sin seis incidentes'; END IF;
  toma:=public.ra_tomar_etapa_v2(eid,'smoke-ensayo','priorizacion');
  IF jsonb_array_length(toma->'incidentes')<>6 THEN RAISE EXCEPTION 'Toma mezcló ámbitos'; END IF;
  PERFORM public.ra_finalizar_priorizacion_v2(eid,'smoke-ensayo',toma,c->'resultado',ARRAY[]::text[],c->'validaciones');
  IF (SELECT count(*) FROM public.necesidades WHERE ejecucion_id=eid)<>6 THEN RAISE EXCEPTION 'Faltan necesidades'; END IF;
  IF p->>'caso'='calculable' THEN
   IF (SELECT sum(demanda_litros) FROM public.necesidades WHERE ejecucion_id=eid)<>15000
   OR EXISTS(SELECT 1 FROM public.necesidades WHERE ejecucion_id=eid AND estado_prioridad<>'calculada') THEN RAISE EXCEPTION 'Caso calculable incorrecto'; END IF;
  ELSE
   IF (SELECT count(*) FROM public.necesidades WHERE ejecucion_id=eid AND estado_prioridad='pendiente' AND demanda_litros IS NULL AND puntaje IS NULL AND posicion IS NULL AND requiere_revision_urgente)<>1 THEN RAISE EXCEPTION 'Ausencia no quedó pendiente urgente'; END IF;
  END IF;
  SELECT count(*) INTO n FROM public.eventos WHERE ejecucion_id=eid;
  r:=public.ra_registrar_ensayo_priorizacion_v2(u,p,'Revisión ficticia del smoke');
  IF r->>'repetido' IS DISTINCT FROM 'true' OR n<>(SELECT count(*) FROM public.eventos WHERE ejecucion_id=eid) THEN RAISE EXCEPTION 'Registro repetido escribió'; END IF;
  r:=public.ra_preparar_priorizacion_v2(eid,u,p->'lote');
  IF r->>'repetido' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Preparación repetida no idempotente'; END IF;
 END LOOP;
 IF base IS DISTINCT FROM public.ra_incidentes_snapshot_v2() THEN RAISE EXCEPTION 'Se alteró el ámbito ciudadano'; END IF;
 -- El ámbito ciudadano puede contener incidentes previos, además del control creado aquí.
 IF public.ra_incidentes_contexto_v2(ee) IS DISTINCT FROM base THEN RAISE EXCEPTION 'Contexto normal ve fixtures o perdió incidentes previos'; END IF;
 -- Un lote ciudadano incompleto no se vuelve válido por la existencia de fixtures.
 IF EXISTS(SELECT 1 FROM public.necesidades WHERE ejecucion_id=ee) THEN RAISE EXCEPTION 'Se calculó el incidente ciudadano'; END IF;
 RAISE NOTICE 'OK: calculable 15000 L, pendiente urgente, dos ámbitos, control ciudadano e idempotencia.';
END $$;
ROLLBACK;
